import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { BackButton } from '@/components/BackButton'
import type { Comment, Post } from '@/types/blog'

export const revalidate = 300

export async function generateStaticParams(): Promise<{ id: string }[]> {
  const posts: Post[] = await fetch(
    'https://jsonplaceholder.typicode.com/posts'
  ).then((res) => res.json())

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

interface BlogPostPageProps {
  params: Promise<{ id: string }>
}

async function getPostData(id: string): Promise<{ post: Post; comments: Comment[] }> {
  const [postResponse, commentsResponse] = await Promise.all([
    fetch(`https://jsonplaceholder.typicode.com/posts/${id}`),
    fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`),
  ])

  if (!postResponse.ok) {
    notFound()
  }

  const post: Post = await postResponse.json()
  const comments: Comment[] = await commentsResponse.json()

  return { post, comments }
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params
  const { post } = await getPostData(id)

  return {
    title: `${post.title} - My Blog`,
    description: post.body.substring(0, 160),
    openGraph: {
      title: post.title,
      description: post.body.substring(0, 160),
    },
  }
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { id } = await params
  const { post, comments } = await getPostData(id)

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

